import React from 'react';
import './StatusList.css';
import type { Item, Status } from '../../types';

export const STATUS_LABELS: Record<Status, string> = {
  'todo': 'To Do',
  'in-progress': 'In Progress',
  'done': 'Done',
  'blocked': 'Blocked',
};

export const SKELETON_COUNT = 6;

// null = loading; array = loaded
const STATUS_ORDER: Status[] = ['todo', 'in-progress', 'done', 'blocked'];

export function statusColor(status: Status): string {
  switch (status) {
    case 'todo': return 'status-todo';
    case 'in-progress': return 'status-in-progress';
    case 'done': return 'status-done';
    case 'blocked': return 'status-blocked';
  }
}

interface StatusListProps {
  items: Item[] | null;
}

export function StatusList({ items }: StatusListProps): React.JSX.Element {
  if (items === null) {
    return (
      <ul role="list" className="status-list">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="status-list-item">
            <span className="skeleton-pill" />
          </li>
        ))}
      </ul>
    );
  }

  const grouped: Record<Status, Item[]> = {
    'todo': [],
    'in-progress': [],
    'done': [],
    'blocked': [],
  };

  for (const item of items) {
    grouped[item.status].push(item);
  }

  return (
    <ul role="list" className="status-list">
      {STATUS_ORDER.flatMap((status) => {
        const group = grouped[status];
        if (group.length === 0) {
          return [];
        }
        return [
          <li key={`header-${status}`} role="presentation" className={`status-list-group-header ${statusColor(status)}`}>
            {STATUS_LABELS[status]}
          </li>,
          ...group.map((item) => (
            <li key={item.id} className={`status-list-item ${statusColor(status)}`}>
              <span className="status-list-item-indicator">{STATUS_LABELS[status]}</span>
              {item.title}
            </li>
          )),
        ];
      })}
    </ul>
  );
}
